function paintBucket(image: number[][], sr: number, sc: number, color: number): number[][] {
  const orig = image[sr][sc];
  if (orig === color) return image;
  const R = image.length, C = image[0].length;
  const stack: number[][] = [[sr, sc]];
  image[sr][sc] = color;
  while (stack.length) {
    const [r, c] = stack.pop()!;
    for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
      if (nr >= 0 && nr < R && nc >= 0 && nc < C && image[nr][nc] === orig) {
        image[nr][nc] = color;
        stack.push([nr, nc]);
      }
    }
  }
  return image;
}

