        orig = image[sr][sc]
        if orig == color:
            return image
        R, C = len(image), len(image[0])
        image[sr][sc] = color
        stack = [(sr, sc)]
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < R and 0 <= nc < C and image[nr][nc] == orig:
                    image[nr][nc] = color
                    stack.append((nr, nc))
        return image

