function paintBucket(image: number[][], sr: number, sc: number, color: number): number[][] {
  const orig = image[sr][sc];
  if (orig === color) return image;
  const R = image.length, C = image[0].length;
  const q: number[] = [sr * C + sc];
  image[sr][sc] = color;
  for (let i = 0; i < q.length; i++) {
    const r = Math.floor(q[i] / C), c = q[i] % C;
    const nbrs = [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]];
    for (const [nr, nc] of nbrs) {
      if (nr < 0 || nr >= R || nc < 0 || nc >= C || image[nr][nc] !== orig) continue;
      image[nr][nc] = color;
      q.push(nr * C + nc);
    }
  }
  return image;
}

